insert into recommendations
  (id, name, destination, tag, interests, window_start, window_end, vibe, description, why_it_fits, evidence_source, verified, priority)
values
  ('pune-dagdusheth', 'Dagdusheth Halwai Ganpati Temple', 'Pune', 'tourist_essential', ARRAY['spiritual']::text[], '06:30', '08:00', 'Bright, loud, genuinely moving', 'Go at dawn, when it''s mostly people on their way to work rather than people on their way to a photo.', '{"spiritual":"It''s the one temple in Pune that locals and visitors both actually mean when they say ''the temple''.","local_life":"Morning darshan here is a daily routine for half the old city, not a tourist ritual."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-shaniwar-wada', 'Shaniwar Wada', 'Pune', 'tourist_essential', ARRAY['history']::text[], '09:00', '10:30', 'Open, sunbaked, more ruin than palace', 'The Peshwa seat of power, burnt down and left as foundations — go for the scale and the gate, not for furnished rooms.', '{"history":"You can''t really read Pune''s Maratha history without standing in this courtyard first."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-aga-khan', 'Aga Khan Palace', 'Pune', 'tourist_essential', ARRAY['history']::text[], '10:45', '12:15', 'Quiet lawns, heavy history', 'Gandhi, Kasturba and Mahadev Desai were interned here. The memorials in the garden land harder than the building does.', '{"history":"It''s the rare freedom-movement site that still feels like a house someone lived in.","nature":"The lawns are the calmest green space you''ll find this close to the centre."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-kelkar-museum', 'Raja Dinkar Kelkar Museum', 'Pune', 'tourist_essential', ARRAY['history', 'local_life']::text[], '11:00', '12:30', 'Dense, cluttered, quietly obsessive', 'One man''s lifetime of collecting ordinary Indian objects — lamps, nutcrackers, door frames. Far better than it sounds.', '{"history":"History told through what people actually used at home, not through kings and dates.","local_life":"The everyday-object collection explains more about how India lived than any fort will."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-sinhagad', 'Sinhagad Fort', 'Pune', 'tourist_essential', ARRAY['nature', 'history']::text[], '06:00', '10:00', 'Cold wind, steep climb, enormous view', 'An hour out of the city and a real climb. Weekend mornings are crowded with Pune''s own trekkers — that''s part of the appeal.', '{"nature":"The best big-landscape morning available within reach of the city.","history":"Tanaji''s fort — the one piece of Maratha history Punekars will bring up unprompted."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-vaishali', 'Vaishali, FC Road', 'Pune', 'local_favourite', ARRAY['food', 'local_life']::text[], '08:00', '09:30', 'Formica tables, unhurried, institution-grade', 'Sambar, filter coffee and decades of students arguing at the same tables. Expect to wait; it''s worth waiting.', '{"food":"This is the breakfast a Punekar would take you to before anything else opens.","local_life":"More of Pune''s actual social life has happened here than at any monument in the city."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-bedekar', 'Bedekar Tea Stall', 'Pune', 'local_favourite', ARRAY['food']::text[], '08:30', '10:00', 'Tiny, brisk, deadly serious about misal', 'Pune misal at its sharpest. Order the kat separately if you want to survive it, and don''t linger — nobody does.', '{"food":"If you eat one thing in Pune that you can''t get properly anywhere else, make it this."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-parvati', 'Parvati Hill', 'Pune', 'local_favourite', ARRAY['spiritual', 'nature']::text[], '06:00', '07:30', 'Stone steps, morning walkers, whole-city view', 'A flight of steps up to an old temple complex, climbed daily by half the neighbourhood. Go before the sun is properly up.', '{"spiritual":"A working temple people climb to out of habit, not a monument they visit.","nature":"The clearest view of Pune you can get without leaving the city."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-pataleshwar', 'Pataleshwar Cave Temple', 'Pune', 'local_favourite', ARRAY['spiritual', 'history']::text[], '07:30', '09:00', 'Dark, cool, startlingly old', 'An 8th-century temple cut straight out of basalt, sitting in the middle of a busy road. Most people drive past it daily.', '{"spiritual":"Still an active shrine, and almost always empty enough to sit in.","history":"Rock-cut, centuries older than anything Peshwa-era in this city."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-vetal-tekdi', 'Vetal Tekdi', 'Pune', 'local_favourite', ARRAY['nature', 'local_life']::text[], '06:00', '07:45', 'Dust, birdsong, regulars who all know each other', 'The city''s own hill. No ticket, no gate — just paths worn in by people who walk them every single morning.', '{"nature":"The closest thing to wilderness inside Pune''s limits.","local_life":"Walking here at 6am is the single most Pune thing you can do."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-tulshibaug', 'Tulshibaug Market', 'Pune', 'local_favourite', ARRAY['local_life']::text[], '17:00', '19:00', 'Narrow, crowded, relentlessly practical', 'Lanes of household goods, bangles and steel vessels behind an old temple. Come to watch the bargaining, not to buy.', '{"local_life":"This is where the city shops for itself, not for visitors."}'::jsonb, 'seeded_anchor', false, 6),
  ('pune-chitale', 'Chitale Bandhu Mithaiwale', 'Pune', 'local_favourite', ARRAY['food']::text[], '16:30', '17:30', 'Queue, counter, no seating, no nonsense', 'Bakarwadi to take home. The shop famously used to shut in the afternoon and the city simply worked around it.', '{"food":"The thing Punekars actually carry with them when they travel."}'::jsonb, 'seeded_anchor', false, 7),
  ('pune-shinde-chhatri', 'Shinde Chhatri, Wanowrie', 'Pune', 'hidden_gem', ARRAY['history']::text[], '15:00', '16:30', 'Ornate, empty, oddly solemn', 'A memorial to Mahadji Shinde with carving far more elaborate than anything at the famous sites — and usually nobody in it.', '{"history":"The best stonework in Pune is in a memorial most visitors never hear about.","spiritual":"Quiet enough to sit in for an hour without anyone hurrying you along."}'::jsonb, 'seeded_anchor', false, 1),
  ('pune-kasba-peth', 'Kasba Peth lanes & Kasba Ganpati', 'Pune', 'hidden_gem', ARRAY['local_life', 'history', 'spiritual']::text[], '09:00', '10:45', 'Old wooden facades, tight lanes, lived-in', 'The oldest part of the city, and the home of Pune''s presiding Ganpati. Walk it slowly; there is nothing to ''see'' and everything to notice.', '{"local_life":"The one walk that shows you what Pune was before it became a metro.","history":"Older than the Peshwas, and still entirely residential.","spiritual":"Kasba Ganpati is the city''s gram daivat — first honours in the festival, every year."}'::jsonb, 'seeded_anchor', false, 2),
  ('pune-taljai', 'Taljai Tekdi', 'Pune', 'hidden_gem', ARRAY['nature']::text[], '06:30', '08:00', 'Wooded, quiet, thinner crowd than Vetal', 'The hill people go to when Vetal Tekdi feels busy. Denser tree cover, more birds, fewer conversations.', '{"nature":"Genuinely peaceful, and almost never mentioned to visitors."}'::jsonb, 'seeded_anchor', false, 3),
  ('pune-marz-o-rin', 'Marz-O-Rin, MG Road', 'Pune', 'hidden_gem', ARRAY['food', 'local_life']::text[], '13:00', '14:30', 'Faded Irani cafe, soft light, slow', 'Sandwiches, cold coffee and an interior that hasn''t been updated in decades — deliberately. An afternoon holdout from an older Pune.', '{"food":"Not a destination dish, just a place worth an unhurried hour.","local_life":"One of the last Irani-cafe afternoons left in the city."}'::jsonb, 'seeded_anchor', false, 4),
  ('pune-pu-la-garden', 'Pu La Deshpande Garden', 'Pune', 'hidden_gem', ARRAY['nature']::text[], '08:00', '09:30', 'Japanese-garden calm, water, raked stone', 'A Japanese-style garden modelled on one in Okayama, sitting incongruously beside a Pune canal. Go early, before the school groups.', '{"nature":"Manicured quiet — the opposite of the hills, and a good counterweight to them."}'::jsonb, 'seeded_anchor', false, 5),
  ('pune-khunya-murlidhar', 'Khunya Murlidhar Temple', 'Pune', 'hidden_gem', ARRAY['spiritual', 'history']::text[], '07:00', '08:30', 'Small, old, tucked behind the noise', 'A peth temple with a grim name and a long story behind it, wedged into a lane most visitors never turn down.', '{"spiritual":"Small enough that you''ll likely have it to yourself.","history":"The kind of place where the story matters more than the building."}'::jsonb, 'seeded_anchor', false, 6),
  ('pune-laxmi-road', 'Laxmi Road at dusk', 'Pune', 'hidden_gem', ARRAY['local_life']::text[], '18:00', '19:30', 'Shoulder-to-shoulder, lit up, chaotic', 'Not a sight — a street. Walk its length in the evening and you''ll understand the city''s density better than any museum will explain it.', '{"local_life":"An hour here beats a day of monuments for actually feeling the place."}'::jsonb, 'seeded_anchor', false, 7)
